import 'package:flutter/material.dart'; import '../utils/constants.dart'; import '../utils/app_routes.dart';
class QuickPhrasesScreen extends StatelessWidget{const QuickPhrasesScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Quick Phrases')),body:ListView.separated(padding:const EdgeInsets.all(18),itemCount:Constants.quickPhrases.length,separatorBuilder:(_,__)=>const Divider(),itemBuilder:(_,i)=>ListTile(leading:const Text('🤟',style:TextStyle(fontSize:28)),title:Text(Constants.quickPhrases[i]),trailing:const Icon(Icons.play_circle_outline),onTap:()=>Navigator.pushNamed(c,AppRoutes.hearingResult,arguments:Constants.quickPhrases[i]))));}
